import{_ as t,o,c as r,ai as i}from"./chunks/framework.Ci0kozOl.js";const h=JSON.parse('{"title":"Agentic Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/agentic/recipes.md","filePath":"3.0/agentic/recipes.md","lastUpdated":1785947307000}'),a={name:"3.0/agentic/recipes.md"};function s(n,e,c,l,p,d){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="agentic-recipes" tabindex="-1">Agentic Recipes <a class="header-anchor" href="#agentic-recipes" aria-label="Permalink to &quot;Agentic Recipes&quot;">​</a></h1><p>Practical, end-to-end playbooks for working on UnoPim <em>with</em> AI. Each recipe states the <strong>goal</strong>, which agentic interface it uses, the <strong>steps</strong> (the prompts and tools involved), and what to <strong>verify</strong> afterwards.</p><p>The three interfaces these recipes draw on:</p><ul><li><strong>AI Agent</strong> — the in-app chat widget (<a href="./ai-agent.html">reference</a>).</li><li><strong>MCP Server</strong> — your IDE&#39;s AI assistant connected to the live instance (<a href="./mcp-server.html">reference</a>).</li><li><strong>Agentic Skills</strong> — UnoPim conventions loaded into your coding agent (<a href="./agent-skills.html">reference</a>).</li></ul><hr><h2 id="recipe-1-—-scaffold-a-connector-with-ai" tabindex="-1">Recipe 1 — Scaffold a Connector with AI <a class="header-anchor" href="#recipe-1-—-scaffold-a-connector-with-ai" aria-label="Permalink to &quot;Recipe 1 — Scaffold a Connector with AI&quot;">​</a></h2><p><strong>Goal:</strong> Stand up a new third-party connector plugin without hand-writing boilerplate.</p><p><strong>Uses:</strong> Agentic Skills (<code>unopim-plugin-development</code>) + MCP Server (<code>dev_tools</code> → <code>generate_plugin</code>, <code>run_command</code>).</p><p><strong>Steps:</strong></p><ol><li>With the <code>unopim-plugin-development</code> skill installed, prompt your coding agent: <blockquote><p><em>&quot;Scaffold a connector plugin named &#39;ShipStation&#39; with a configuration page, credential storage, and a connection test.&quot;</em></p></blockquote></li><li>The skill supplies UnoPim&#39;s package conventions (service provider, <code>Database/Migration/</code> folder, <code>[&#39;admin&#39;]</code> middleware, repository pattern); the MCP <code>generate_plugin</code> action writes the directory structure, <code>composer.json</code>, and base classes into <code>packages/Webkul/ShipStation</code>.</li><li>Run migrations through the bridge: <blockquote><p><em>&quot;Run <code>php artisan migrate</code>.&quot;</em> → MCP <code>run_command</code>.</p></blockquote></li></ol><p><strong>Verify:</strong> Ask the agent to <code>read_file</code> the generated <code>ServiceProvider</code>, then confirm the plugin&#39;s config page loads in the admin panel. Run <code>vendor/bin/pint --test</code>.</p><hr><h2 id="recipe-2-—-bulk-attribute-enrichment" tabindex="-1">Recipe 2 — Bulk Attribute Enrichment <a class="header-anchor" href="#recipe-2-—-bulk-attribute-enrichment" aria-label="Permalink to &quot;Recipe 2 — Bulk Attribute Enrichment&quot;">​</a></h2><p><strong>Goal:</strong> Fill missing descriptions across hundreds of products.</p><p><strong>Uses:</strong> AI Agent (search + content generation + bulk edit + auto-translation).</p><p><strong>Steps:</strong></p><ol><li><blockquote><p><em>&quot;Find products without a description created in the last 24 hours.&quot;</em> → the agent calls <code>SearchProducts</code>.</p></blockquote></li><li><blockquote><p><em>&quot;Generate a 200-word SEO-friendly description for each from its name and attributes.&quot;</em> → <code>GenerateContent</code>.</p></blockquote></li><li><blockquote><p><em>&quot;Apply the descriptions and translate them to all active locales.&quot;</em> → <code>BulkEdit</code>, then the <code>TranslateProductValuesJob</code> runs on the queue.</p></blockquote></li></ol><p><strong>Verify:</strong> Spot-check a few products in the admin panel; confirm locale-dependent fields populated for each active locale. If <code>approval_mode</code> is <code>review</code>, approve the changeset from the <a href="./ai-agent.html#approval-queue">approval queue</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For products created before auto-translation was enabled, run the CLI alternative: <code>php artisan unopim:translate</code>.</p></div><hr><h2 id="recipe-3-—-catalog-completeness-diagnostics" tabindex="-1">Recipe 3 — Catalog Completeness Diagnostics <a class="header-anchor" href="#recipe-3-—-catalog-completeness-diagnostics" aria-label="Permalink to &quot;Recipe 3 — Catalog Completeness Diagnostics&quot;">​</a></h2><p><strong>Goal:</strong> Find why a product isn&#39;t appearing in a channel and fix the gaps.</p><p><strong>Uses:</strong> MCP Server (<code>get_product</code>, <code>get_catalog_schema</code>, <code>upsert_products</code>).</p><p><strong>Steps:</strong></p><ol><li><blockquote><p><em>&quot;Check product SKU &#39;PHONE-001&#39; completeness for channel &#39;default&#39;. If it&#39;s below 100%, list the missing required attributes.&quot;</em></p></blockquote></li><li>The assistant fetches the product with its completeness data and reports the missing required attributes.</li><li><blockquote><p><em>&quot;Fill the missing attributes with sensible values and upsert.&quot;</em> → <code>upsert_products</code> (max 50 per atomic batch).</p></blockquote></li></ol><p><strong>Verify:</strong> Re-run the completeness check; confirm 100% for the target channel. Confirm the product now surfaces in that channel.</p><hr><h2 id="recipe-4-—-mass-category-re-assignment" tabindex="-1">Recipe 4 — Mass Category Re-assignment <a class="header-anchor" href="#recipe-4-—-mass-category-re-assignment" aria-label="Permalink to &quot;Recipe 4 — Mass Category Re-assignment&quot;">​</a></h2><p><strong>Goal:</strong> Restructure the catalog — move a set of products to a new category branch.</p><p><strong>Uses:</strong> AI Agent (<code>SearchProducts</code>, <code>AssignCategories</code>, <code>BulkEdit</code>).</p><p><strong>Steps:</strong></p><ol><li><blockquote><p><em>&quot;Find all products in the &#39;Winter Wear&#39; category.&quot;</em></p></blockquote></li><li><blockquote><p><em>&quot;Assign them to &#39;Seasonal &gt; Winter&#39; and remove the old &#39;Winter Wear&#39; assignment.&quot;</em></p></blockquote></li></ol><p><strong>Verify:</strong> Confirm the count of re-assigned products matches the original search count; check the category tree in the admin panel. Use <code>review</code> approval mode for large moves so the changeset is auditable and reversible.</p><hr><h2 id="recipe-5-—-define-attributes-by-description" tabindex="-1">Recipe 5 — Define Attributes by Description <a class="header-anchor" href="#recipe-5-—-define-attributes-by-description" aria-label="Permalink to &quot;Recipe 5 — Define Attributes by Description&quot;">​</a></h2><p><strong>Goal:</strong> Rapidly prototype catalog structure during development.</p><p><strong>Uses:</strong> MCP Server (<code>upsert_attributes</code>, <code>upsert_attribute_groups</code>) or AI Agent (<code>CreateAttribute</code>, <code>ManageFamilies</code>).</p><p><strong>Steps:</strong></p><ol><li><blockquote><p><em>&quot;Create a select-type attribute &#39;Fabric Material&#39; with options Cotton, Silk, Wool.&quot;</em></p></blockquote></li><li><blockquote><p><em>&quot;Add it to the &#39;Clothing&#39; attribute group.&quot;</em></p></blockquote></li></ol><p><strong>Verify:</strong> Confirm the attribute and its options exist via <code>search_attributes</code>, and that it renders on a product in the relevant family.</p><hr><h2 id="recipe-6-—-ai-assisted-test-review-loop" tabindex="-1">Recipe 6 — AI-Assisted Test &amp; Review Loop <a class="header-anchor" href="#recipe-6-—-ai-assisted-test-review-loop" aria-label="Permalink to &quot;Recipe 6 — AI-Assisted Test &amp; Review Loop&quot;">​</a></h2><p><strong>Goal:</strong> Ship a change that passes the UnoPim development pipeline.</p><p><strong>Uses:</strong> Agentic Skills (<code>unopim-dev-cycle</code>, <code>unopim-code-review</code>) + MCP Server (<code>generate_test</code>, <code>run_command</code>).</p><p><strong>Steps:</strong></p><ol><li><blockquote><p><em>&quot;Generate a Pest test for the new <code>ShipStationRepository</code>.&quot;</em> → MCP <code>generate_test</code> (or <code>mcp:make test</code>).</p></blockquote></li><li><blockquote><p><em>&quot;Run the test.&quot;</em> → <code>run_command</code> → <code>vendor/bin/pest</code>.</p></blockquote></li><li><blockquote><p><em>&quot;Review my changes against UnoPim standards before I open a PR.&quot;</em> → the <code>unopim-code-review</code> skill flags convention violations (table prefix, route middleware, hardcoded strings, repository pattern).</p></blockquote></li></ol><p><strong>Verify:</strong> Tests pass, <code>vendor/bin/pint --test</code> reports zero issues, and <code>php artisan unopim:translations:check</code> passes with zero missing keys.</p><hr><h2 id="recipe-7-—-reusable-workflow-as-a-skill" tabindex="-1">Recipe 7 — Reusable Workflow as a Skill <a class="header-anchor" href="#recipe-7-—-reusable-workflow-as-a-skill" aria-label="Permalink to &quot;Recipe 7 — Reusable Workflow as a Skill&quot;">​</a></h2><p><strong>Goal:</strong> Stop re-typing a multi-step instruction you run often.</p><p><strong>Uses:</strong> Dynamic Skills (MCP) — see <a href="./extending-mcp.html#dynamic-skills-low-code">Extending the MCP Bridge</a>.</p><p><strong>Steps:</strong></p><ol><li>Drop a <code>SKILL.md</code> into <code>.ai/skills/audit-channel-pricing/</code> describing the steps (search products, compare prices across two channels, report mismatches).</li><li>The bridge registers <code>execute_audit_channel_pricing</code>.</li><li>Invoke it any time instead of re-explaining the sequence.</li></ol><p><strong>Verify:</strong> Run the new tool from your AI editor and confirm it produces the expected mismatch report.</p><hr><h2 id="general-best-practices" tabindex="-1">General Best Practices <a class="header-anchor" href="#general-best-practices" aria-label="Permalink to &quot;General Best Practices&quot;">​</a></h2><ul><li><strong>Discover before acting</strong> — call <code>get_catalog_schema</code> first so the assistant knows your custom attributes and filterable fields.</li><li><strong>Keep batches atomic</strong> — <code>upsert_*</code> tools cap at 50 items per call for clean error reporting.</li><li><strong>Use <code>review</code> mode for bulk changes</strong> — queue AI-driven mutations as changesets so they&#39;re auditable and reversible before they hit the catalog.</li><li><strong>Sequence read → write → verify</strong> — read the current state, make the change, then confirm with a follow-up search or completeness check.</li><li><strong>Let skills enforce conventions</strong> — keep the relevant Agentic Skill active so generated code respects UnoPim&#39;s standards the first time.</li></ul>',57)])])}const g=t(a,[["render",s]]);export{h as __pageData,g as default};
